-- eFootyTactics AI - Seed 105+ Players (eFootball Realism)
alter table public.players add column if not exists secondary_positions text[] default '{}';

on conflict (id) do update set
  name = excluded.name,
  club = excluded.club,
  nationality = excluded.nationality,
  primary_position = excluded.primary_position,
  secondary_positions = excluded.secondary_positions,
  overall_rating = excluded.overall_rating,
  player_playstyle = excluded.player_playstyle,
  key_stats = excluded.key_stats,
  skills = excluded.skills,
  image_url = excluded.image_url;